export function SplitView({
  heading = "{{heading}}",
  orientation = "{{orientation}}",
  accent = "{{accent}}",
  ratio = {{ratio}},
  showSecondary = {{showSecondary}},
}) {
  const vertical = orientation === "vertical";
  return (
    <div style={{ fontFamily: "system-ui, sans-serif", fontSize: 13.5, color: "#241430", display: "flex", flexDirection: vertical ? "column" : "row", height: vertical ? 320 : undefined, maxWidth: 440, width: 440, border: "1px solid #24143020", borderRadius: 12, overflow: "hidden", boxSizing: "border-box" }}>
      <nav aria-label={heading} style={{ flex: `0 0 ${ratio}%`, background: "#fff", padding: 12, boxSizing: "border-box", overflow: "auto", borderRight: vertical ? "none" : "1px solid #24143020", borderBottom: vertical ? "1px solid #24143020" : "none" }}>
        <h3 style={{ margin: "0 0 8px", fontSize: 13, fontWeight: 700 }}>{heading}</h3>
        <ul style={{ listStyle: "none", margin: 0, padding: 0 }}>
          <li aria-current="true" style={{ padding: "6px 8px", borderRadius: 6, background: accent, fontWeight: 700 }}>Q3 budget review</li>
          <li style={{ padding: "6px 8px", borderRadius: 6 }}>Design crit notes</li>
          <li style={{ padding: "6px 8px", borderRadius: 6 }}>Release checklist</li>
        </ul>
      </nav>
      <section aria-label="Message" style={{ flex: 1, padding: 14, boxSizing: "border-box", background: "#FAF7F2", minWidth: 0, display: showSecondary ? "block" : "grid", placeItems: showSecondary ? undefined : "center", textAlign: showSecondary ? "left" : "center" }}>
        {showSecondary ? (
          <>
            <h4 style={{ margin: "0 0 6px", fontSize: 14, fontWeight: 700 }}>Q3 budget review</h4>
            <p style={{ margin: 0, color: "#241430b3" }}>Attaching the updated numbers for review before Friday's sync.</p>
          </>
        ) : (
          <p style={{ margin: 0, color: "#241430b3" }}>Select an item to preview it here.</p>
        )}
      </section>
    </div>
  );
}
